package com.confApi.plantao;
import com.confApi.authv2.V2;import com.fasterxml.jackson.databind.JsonNode;import java.util.*;import org.springframework.stereotype.Service;
/** Business rule and transport. Persistence and one-use validation belong to Manager. */
@Service public class PlantaoTokenService {
 protected JsonNode call(String route,Object body){return V2.request(V2.setting("AUTH_V2_MANAGER_URL"),route,"POST",body,V2.token("AUTH_V2_MANAGER_TOKEN_FILE"),null);}
 private boolean reference(String value){return value!=null&&value.matches("[A-Za-z0-9_-]{32,128}");}
 public PlantaoTokenResponse gerar(PlantaoTokenRequest r,String authorization){if(r==null||r.login()==null||r.login().isBlank()||!Set.of("APP","EMAIL").contains(Objects.toString(r.canal(),""))||!reference(r.reference()))return PlantaoTokenResponse.falha("Solicitacao de plantao invalida.");
  try{var rs=call("/internal/v2/operacoes/desafios",Map.of("login",r.login().strip(),"purpose","PLANTAO","channel",r.canal(),"reference",r.reference()));String id=rs.path("challengeId").asText();if(!id.matches("[a-f0-9-]{36}")||!r.reference().equals(rs.path("reference").asText())||!"PLANTAO".equals(rs.path("purpose").asText())||!"PENDENTE".equals(rs.path("state").asText()))throw new V2.Failure(503);return new PlantaoTokenResponse(true,null,"Confirme a solicitacao de plantao.",id,r.reference(),rs.path("expiresAt").asText());}catch(V2.Failure e){return PlantaoTokenResponse.falha("Nao foi possivel criar a confirmacao de plantao.");}}
 public PlantaoTokenResponse validar(PlantaoTokenValidationRequest r){if(r==null||r.token()==null||!r.token().matches("[0-9]{4}")||r.challengeId()==null||!r.challengeId().matches("[a-f0-9-]{36}")||!reference(r.reference()))return PlantaoTokenResponse.falha("Codigo invalido.");
  try{var rs=call("/internal/v2/operacoes/desafios/"+r.challengeId()+"/validar",Map.of("code",r.token(),"purpose","PLANTAO","reference",r.reference()));if(!rs.path("authenticated").asBoolean(false)||!r.challengeId().equals(rs.path("challengeId").asText()))return PlantaoTokenResponse.falha("Codigo invalido ou expirado.");return new PlantaoTokenResponse(true,null,"Confirmacao concluida.",r.challengeId(),r.reference(),null);}catch(V2.Failure e){return PlantaoTokenResponse.falha("Codigo invalido ou servico indisponivel.");}}
}
